WHERE PROC_INST_ID_ = #{processInstanceId, jdbcType=VARCHAR}
  AND TASK_ID_ = #{taskId, jdbcType=VARCHAR}
  AND ASSIGNEE_ID_ = #{assigneeId, jdbcType=VARCHAR}
  AND HANDLE_STATUS_ <> 'DONE'
  AND IS_REVOKED_ = 0

SELECT * FROM BIZ_HANDLE_RECORD_
WHERE PROC_INST_ID_ = #{processInstanceId, jdbcType=VARCHAR}
ORDER BY CREATE_TIME_ ASC, ID_ ASC

