UPDATE BIZ_HANDLE_RECORD_
SET IS_REVOKED_ = 1,
    REVOKE_TIME_ = #{revokeTime, jdbcType=TIMESTAMP},
    REVOKE_REASON_ = #{revokeReason, jdbcType=VARCHAR},
    UPDATE_TIME_ = #{revokeTime, jdbcType=TIMESTAMP}
WHERE ID_ = #{id, jdbcType=VARCHAR}
  AND SENDER_ID_ = #{senderUserId, jdbcType=VARCHAR}
  AND HANDLE_STATUS_ <> 'DONE'
  AND IS_REVOKED_ = 0
